mapper.select:
SELECT c.id, c.name, c.room, c.begin_date AS beginDate, c.end_date AS endDate, c.master_id AS masterId, c.subject, c.create_time AS createTime, c.update_time AS updateTime, -- 获取班主任姓名，如果没有分配则显示为空 IFNULL(e.name, '未分配') AS masterName, -- 根据当前日期动态计算状态 CASE WHEN CURDATE() > c.end_date THEN '已结课' WHEN CURDATE() < c.begin_date THEN '未开班' ELSE '在读中' END AS status FROM clazz c LEFT JOIN emp e ON c.master_id = e.id
AND c.name LIKE CONCAT('%', #{name}, '%')
AND c.begin_date >= #{begin}
AND c.end_date <= #{end}
